.form-locked {
    position: relative;
    opacity: 0.6;
}

.form-locked form {
    pointer-events: none;
}

.form-locked::after {
    content: "FORM LOCKED - All reports have been copied";
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
