body {
    font-family: 'Arial', sans-serif;
    background: #1a237e;
    color: #333;
    padding: 20px;
    line-height: 1.2;
    min-height: 100vh;
}

body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: none;
    pointer-events: none;
    z-index: 1;
}

.form-wrapper {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-wrap: wrap;
    position: relative;
    z-index: 2;
}

.form-container {
    width: 700px;
    font-weight: bold;
    background: linear-gradient(to bottom, #ffffff 0%, #f5f5f5 100%);
    padding: 25px;
    border-radius: 12px;
