    text-align: center;
    margin-top: 20px;
    font-size: 28px;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.1);
}

label, textarea, select, input, button {
    display: block;
    width: 100%;
    margin: 5px 0;
    font-size: 14px;
    font-family: Arial, sans-serif;
}

textarea, select, input[type="text"], input[type="number"], button {
    padding: 10px;
    border-radius: 6px;
    box-sizing: border-box;
    transition: all 0.3s ease;
    background-color: white;
}

textarea {
    border: 3px solid #d32f2f;
    min-height: 60px;
