  1335→function applyCompletedStyle(element) {
  1336→    // Check if this is a checkbox container - if so, don't override display property
  1337→    if (element.classList.contains('checkbox-list')) {
  1338→        // For checkbox containers, only add the class and let CSS handle the styling
  1339→        element.classList.add('field-completed');
  1340→    } else {
  1341→        // For regular form fields, apply the styling with important
  1342→        element.style.setProperty('border', '3px solid #2e7d32', 'important');
  1343→        element.style.setProperty('background-color', 'rgba(46, 125, 50, 0.15)', 'important');
  1344→        element.classList.add('field-completed');
  1345→    }
  1346→}
  1347→
  1348→function applyIncompleteStyle(element) {
  1349→    // Check if this is a checkbox container - if so, don't override display property
  1350→    if (element.classList.contains('checkbox-list')) {
  1351→        // For checkbox containers, only remove the class and let CSS handle the styling
  1352→        element.classList.remove('field-completed');
  1353→    } else {
  1354→        // For regular form fields, apply the styling with important
  1355→        if (element.classList.contains('child-at-risk-select') || element.id === 'thriveLevel' || element.id === 'childAtRisk') {
  1356→            element.style.setProperty('border', '3px solid #d32f2f', 'important');
  1357→        } else if (element.tagName === 'SELECT' && !element.classList.contains('child-at-risk-select')) {
  1358→            element.style.setProperty('border', '3px solid #2e7d32', 'important');
  1359→        } else {
  1360→            element.style.setProperty('border', '3px solid #d32f2f', 'important');
  1361→        }
  1362→        element.style.setProperty('background-color', '', 'important');
  1363→        element.classList.remove('field-completed');
  1364→    }
  1365→}
