                const schoolCheckboxLabel = document.createElement('label');
                schoolCheckboxLabel.className = 'checkbox-label';
                schoolCheckboxLabel.textContent = 'U/K';
                schoolCheckboxLabel.setAttribute('for', `childSchool${i}Unknown`);
                schoolCheckboxLabel.style.width = '8%';
                schoolCheckboxLabel.style.textAlign = 'center';

                schoolFieldContainer.appendChild(schoolInput);
                schoolFieldContainer.appendChild(schoolCheckbox);
                schoolFieldContainer.appendChild(schoolCheckboxLabel);
                schoolDiv.appendChild(schoolFieldContainer);
                schoolContainer.appendChild(schoolDiv);
            }
        }

        updateChildText(count > 1);
        updateFieldStyles();
    } else {
        container.style.display = 'none';
        inputsContainer.innerHTML = '';
        schoolContainer.innerHTML = '';
        const schoolLabel = document.createElement('label');
        schoolLabel.setAttribute('for', 'childSchool');
        schoolLabel.textContent = 'Which school/place of education does the child attend?';
        schoolContainer.appendChild(schoolLabel);

        const schoolInput = document.createElement('input');
        schoolInput.type = 'text';
        schoolInput.id = 'childSchool';
        schoolInput.name = 'Which school/place of education does the child attend?';
        schoolInput.required = true;
        schoolContainer.appendChild(schoolInput);

        updateChildText(false);
        updateFieldStyles();
    }

    if (count) {
        applyCompletedStyle(document.getElementById('childrenCount'));
    }
}

