function handleThriveLevelChange() {
    const thriveLevel = document.getElementById('thriveLevel');
    const riskLabel = document.getElementById('riskLabel');

    // Remove all previous color classes
    thriveLevel.classList.remove('thrive-high', 'thrive-medium', 'thrive-low');

    // Update the Risk label to show the THRIVE level + Risk and apply color coding
    if (thriveLevel.value) {
        riskLabel.textContent = `R: (${thriveLevel.value} Risk)`;

        // Apply appropriate color class based on selected value
        if (thriveLevel.value === 'High') {
            thriveLevel.classList.add('thrive-high');
        } else if (thriveLevel.value === 'Medium') {
            thriveLevel.classList.add('thrive-medium');
        } else if (thriveLevel.value === 'Low') {
            thriveLevel.classList.add('thrive-low');
        }
    } else {
        riskLabel.textContent = 'R:';
    }
}

